TRMAP={'de':{},'ms':{},'ar':{},'zh':{},'tr':{}}
def TRREG(en,de='',ms='',ar='',zh='',tr=''):
    k=html.unescape(en).strip()
    if de:TRMAP['de'][k]=de
    if ms:TRMAP['ms'][k]=ms
    if ar:TRMAP['ar'][k]=ar
    if zh:TRMAP['zh'][k]=zh
    if tr:TRMAP['tr'][k]=tr
try:
    import i18n_data; i18n_data.register(TRREG)
except Exception as _e:
    print("i18n_data not loaded:", _e)

